const input = items[0].json || {};
const start = String(input.startDateTime || '').trim();
const end = String(input.endDateTime || '').trim();
return [{ json: { ...input, graphUrl: `https://graph.microsoft.com/v1.0/me/calendarView?startDateTime=${encodeURIComponent(start)}&endDateTime=${encodeURIComponent(end)}&$select=id,subject,start,end,attendees,webLink&$orderby=start/dateTime` } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const data = items[0].json || {};
if (data.error) return fail('WF_CHECK_CALENDAR_CONFLICTS', data.error);
const events = data.value || [];
const sameTitle = events.filter(e => String(e.subject || '').toLowerCase() === String(input.subject || '').toLowerCase());
const duplicate = sameTitle.some(e => JSON.stringify(e.attendees || []).toLowerCase().includes(String(input.attendeeEmail || '').toLowerCase()));
const conflict = events.length > 0 && !duplicate;
return pass(`Calendar conflict check complete.\nDuplicate detected: ${duplicate ? 'Yes' : 'No'}\nConflict detected: ${conflict ? 'Yes' : 'No'}\nEvents in requested time: ${events.length}\nVerification status: Passed`, { duplicate, conflict, events });
